function parseJson(value) {
  if (value && typeof value === 'object') return value;
  const text = String(value || '').trim();
  if (!text) return null;

  try {
    return JSON.parse(text);
  } catch (error) {
    const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
    const object = text.match(/\{[\s\S]*\}/);
    const candidate = fenced?.[1] || object?.[0];
    if (!candidate) return null;

    try {
      return JSON.parse(candidate);
    } catch (nestedError) {
      return null;
    }
  }
}

function asArray(value) {
  return Array.isArray(value) ? value.filter(Boolean) : [];
}

function normalizeNumber(value) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) && numberValue > 0 ? numberValue : null;
}

function normalizeNavigation(value, intent) {
  if (value && value.primary_path) return value;

  if (intent === 'account_help' || intent === 'login_help') {
    return {
      primary_label: intent === 'login_help' ? 'Se connecter' : 'Creer un compte',
      primary_path: intent === 'login_help' ? '/login' : '/register',
      secondary_label: intent === 'login_help' ? 'Creer un compte' : 'Se connecter',
      secondary_path: intent === 'login_help' ? '/register' : '/login'
    };
  }

  if (intent === 'service_optimizer') {
    return {
      primary_label: 'Publier un service',
      primary_path: '/freelancer/services',
      secondary_label: 'Completer mon profil',
      secondary_path: '/freelancer/profile'
    };
  }

  if (intent === 'become_freelance' || intent === 'freelance_profile') {
    return {
      primary_label: 'Creer un compte freelance',
      primary_path: '/register',
      secondary_label: 'Explorer les services',
      secondary_path: '/services'
    };
  }

  if (intent === 'platform_help') {
    return {
      primary_label: 'Creer un compte',
      primary_path: '/register',
      secondary_label: 'Se connecter',
      secondary_path: '/login'
    };
  }

  return {
    primary_label: 'Ouvrir le matching',
    primary_path: '/services#matching-assistant',
    secondary_label: 'Explorer les services',
    secondary_path: '/services'
  };
}

function formatBrief(brief) {
  if (!brief) return '';

  return [
    'Brouillon de besoin :',
    `- Categorie : ${brief.category || 'a confirmer'}`,
    `- Ville : ${brief.city || 'a confirmer'}`,
    `- Mode : ${brief.mode || 'a confirmer'}`,
    `- Budget : ${brief.budget ?? 'a confirmer'} MAD`,
    `- Delai : ${brief.deadline_days ?? 'a confirmer'} jours`,
    `- Objectif : ${brief.objective || 'a confirmer'}`,
    `- Livrables : ${asArray(brief.deliverables).length ? asArray(brief.deliverables).join(', ') : 'a confirmer'}`
  ].join('\n');
}

function formatProfile(profile) {
  if (!profile) return '';

  return [
    'Brouillon de profil freelance :',
    `- Headline : ${profile.headline || 'a confirmer'}`,
    `- Bio : ${profile.professional_bio || 'a confirmer'}`,
    `- Competences : ${asArray(profile.skills).length ? asArray(profile.skills).join(', ') : 'a confirmer'}`,
    `- Ville : ${profile.city || 'a confirmer'}`,
    `- Disponibilite : ${profile.availability || 'a confirmer'}`,
    `- Tarif horaire : ${profile.hourly_rate ?? 'a confirmer'} MAD`,
    `- Portfolio : ${profile.portfolio_url || 'a confirmer'}`,
    `- Categories : ${asArray(profile.primary_categories).length ? asArray(profile.primary_categories).join(', ') : 'a confirmer'}`,
    `- Mode : ${profile.remote_mode || 'a confirmer'}`
  ].join('\n');
}

function normalizeServiceDraft(value) {
  if (!value || typeof value !== 'object') return null;

  return {
    title: value.title || null,
    short_description: value.short_description || value.shortDescription || null,
    description: value.description || null,
    suggested_price: normalizeNumber(value.suggested_price ?? value.suggestedPrice),
    keywords: asArray(value.keywords || value.mots_cles),
    category: value.category || null,
    delivery_time_days: normalizeNumber(value.delivery_time_days ?? value.deliveryTimeDays),
    execution_mode: value.execution_mode || value.executionMode || null,
    deliverables: asArray(value.deliverables)
  };
}

function formatServiceDraft(serviceDraft) {
  if (!serviceDraft) return '';

  return [
    'Offre service amelioree :',
    `- Titre : ${serviceDraft.title || 'a confirmer'}`,
    `- Description courte : ${serviceDraft.short_description || 'a confirmer'}`,
    `- Description : ${serviceDraft.description || 'a confirmer'}`,
    `- Prix conseille : ${serviceDraft.suggested_price ?? 'a confirmer'} MAD`,
    `- Mots-cles : ${serviceDraft.keywords.length ? serviceDraft.keywords.join(', ') : 'a confirmer'}`,
    `- Categorie : ${serviceDraft.category || 'a confirmer'}`,
    `- Delai : ${serviceDraft.delivery_time_days ?? 'a confirmer'} jours`,
    `- Mode : ${serviceDraft.execution_mode || 'a confirmer'}`,
    `- Livrables : ${serviceDraft.deliverables.length ? serviceDraft.deliverables.join(', ') : 'a confirmer'}`
  ].join('\n');
}

function normalizeRecommendations(value) {
  return asArray(value).slice(0, 3).map((item) => {
    const service = item.service || item;
    return {
      service_id: service.id ?? item.service_id ?? item.serviceId ?? item.id ?? null,
      title: service.title || item.title || 'Service recommande',
      score: normalizeNumber(item.score) ?? normalizeNumber(service.score) ?? null,
      reasons: asArray(item.reasons),
      price: normalizeNumber(service.price ?? item.price),
      city: service.city || item.city || null
    };
  });
}

function formatRecommendations(recommendations) {
  if (!recommendations.length) return '';

  const lines = recommendations.map((item, index) => {
    const percent = item.score ? `${Math.round(item.score * 100)}%` : 'match';
    const price = item.price ? ` - ${item.price} MAD` : '';
    const city = item.city ? ` - ${item.city}` : '';
    const reasons = item.reasons.length ? ` (${item.reasons.slice(0, 2).join(', ')})` : '';
    return `${index + 1}. ${item.title} - ${percent}${price}${city}${reasons}`;
  });

  return ['Services recommandes :', ...lines].join('\n');
}

function formatGlobalOutput(structured) {
  const lines = [];
  if (structured.assistantMessage) lines.push(structured.assistantMessage);

  const briefText = formatBrief(structured.brief);
  if (briefText) lines.push(briefText);

  const profileText = formatProfile(structured.profile);
  if (profileText) lines.push(profileText);

  const serviceDraftText = formatServiceDraft(structured.serviceDraft);
  if (serviceDraftText) lines.push(serviceDraftText);

  const recommendationText = formatRecommendations(structured.recommendations);
  if (recommendationText) lines.push(recommendationText);

  if (structured.navigation?.primary_label && structured.navigation?.primary_path) {
    lines.push(`Action conseillee : ${structured.navigation.primary_label} (${structured.navigation.primary_path})`);
  }

  if (structured.missingFields.length) {
    lines.push(`A confirmer : ${structured.missingFields.join(', ')}`);
  }

  return lines.filter(Boolean).join('\n\n') || 'Expliquez en une phrase ce que vous cherchez.';
}

const rawOutput = $json.output ?? $json.text ?? $json.message ?? $json.response ?? $json;
const parsed = parseJson(rawOutput);

if (!parsed) {
  const fallbackMessage = typeof rawOutput === 'string' ? rawOutput : JSON.stringify(rawOutput);
  const structured = {
    status: 'need_more_info',
    intent: 'unknown',
    assistantMessage: fallbackMessage || 'Expliquez en une phrase ce que vous cherchez : un service, un profil freelance, une offre a ameliorer ou une aide plateforme.',
    brief: null,
    profile: null,
    serviceDraft: null,
    recommendations: [],
    navigation: normalizeNavigation(null, 'unknown'),
    missingFields: ['objective'],
    nextAction: 'ask_clarification'
  };

  return [{ json: { output: formatGlobalOutput(structured), structured } }];
}

const intent = parsed.intent || 'unknown';
const structured = {
  status: parsed.status || 'ready',
  intent,
  assistantMessage: parsed.assistant_message || parsed.assistantMessage || '',
  brief: parsed.brief || null,
  profile: parsed.profile || null,
  serviceDraft: normalizeServiceDraft(parsed.service_draft || parsed.serviceDraft),
  recommendations: normalizeRecommendations(parsed.recommendations),
  navigation: normalizeNavigation(parsed.navigation, intent),
  missingFields: asArray(parsed.missing_fields || parsed.missingFields),
  nextAction: parsed.next_action || parsed.nextAction || null
};

if (structured.profile && parsed.profile_completion_score !== undefined) {
  structured.profile.profile_completion_score = parsed.profile_completion_score;
}

return [{ json: { output: formatGlobalOutput(structured), structured } }];
